var staff = new List<Employee>();
Console.WriteLine($"Total: {staff.Sum(e => e.MonthlyPay()):N2}");

abstract class Employee
{
    public string Name { get; }
    protected Employee(string name) => Name = name;
    public abstract decimal MonthlyPay();
    public virtual string Describe() => "employee";
    public override string ToString() => $"{Name} ({Describe()}): {MonthlyPay():N2}";
}

